using System;using System.Data;using System.Drawing;using System.IO;using System.Text;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;namespace AshkanJobCenter.UI{public class ReportsPage:UserControl{ComboBox report;DataGridView grid;public ReportsPage(){Dock=DockStyle.Fill;BackColor=Theme.Background;var top=new FlowLayoutPanel{Dock=DockStyle.Top,Height=70,Padding=new Padding(8)};report=new ComboBox{Width=240,DropDownStyle=ComboBoxStyle.DropDownList};report.Items.AddRange(new object[]{L.Fa?"قیف استخدام":"Recruitment funnel",L.Fa?"فرصت‌های شغلی":"Jobs report",L.Fa?"کارجویان":"Candidates report",L.Fa?"مصاحبه‌ها":"Interviews report"});report.SelectedIndex=0;var load=Ui.Button(L.Fa?"نمایش گزارش":"Run report");load.Click+=(s,e)=>LoadReport();var csv=Ui.Button(L.Fa?"خروجی CSV":"Export CSV",false);csv.Click+=(s,e)=>ExportCsv();top.Controls.AddRange(new Control[]{report,load,csv});grid=Ui.Grid();Controls.Add(grid);Controls.Add(top);LoadReport();}void LoadReport(){switch(report.SelectedIndex){case 1:grid.DataSource=Database.Query("SELECT j.Id,j.Title,c.Name Company,j.City,j.Status,j.CreatedAt,(SELECT COUNT(*) FROM Applications a WHERE a.JobId=j.Id) Applications FROM Jobs j LEFT JOIN Companies c ON c.Id=j.CompanyId ORDER BY j.Id DESC");break;case 2:grid.DataSource=Database.Query("SELECT c.Id,c.FullName,c.City,c.PrimarySkill,c.ExperienceYears,c.Status,(SELECT COUNT(*) FROM Applications a WHERE a.CandidateId=c.Id) Applications FROM Candidates c ORDER BY c.Id DESC");break;case 3:grid.DataSource=Database.Query("SELECT i.Id,c.FullName Candidate,j.Title Job,i.ScheduledAt,i.InterviewType,i.Interviewer,i.Status FROM Interviews i JOIN Applications a ON a.Id=i.ApplicationId JOIN Candidates c ON c.Id=a.CandidateId JOIN Jobs j ON j.Id=a.JobId ORDER BY i.ScheduledAt DESC");break;default:grid.DataSource=Database.Query("SELECT Stage,COUNT(*) Total,CAST(AVG(CAST(ISNULL(Score,0) AS FLOAT)) AS DECIMAL(10,1)) AvgScore FROM Applications GROUP BY Stage ORDER BY Total DESC");break;}}void ExportCsv(){var dt=grid.DataSource as DataTable;if(dt==null||dt.Rows.Count==0)return;using(var d=new SaveFileDialog{Filter="CSV (*.csv)|*.csv",FileName="AshkanJobCenter-report.csv"})if(d.ShowDialog()==DialogResult.OK){var sb=new StringBuilder();for(int i=0;i<dt.Columns.Count;i++){if(i>0)sb.Append(',');sb.Append(E(dt.Columns[i].ColumnName));}sb.AppendLine();foreach(DataRow r in dt.Rows){for(int i=0;i<dt.Columns.Count;i++){if(i>0)sb.Append(',');sb.Append(E(Convert.ToString(r[i])));}sb.AppendLine();}File.WriteAllText(d.FileName,sb.ToString(),new UTF8Encoding(true));Database.Audit("Export","Report",report.Text);MessageBox.Show(L.Fa?"گزارش ذخیره شد.":"Report exported.");}}string E(string s){return "\""+(s??"").Replace("\"","\"\"")+"\"";}}}